1. SELECT a.asset_name FROM assets a WHERE a.asset_id NOT IN (SELECT s.asset_id FROM sensor_readings s WHERE s.alarm_flag = 1) ORDER BY a.asset_name;

2. SELECT a.asset_name FROM assets a LEFT JOIN sensor_readings s ON a.asset_id = s.asset_id AND s.alarm_flag = 1 WHERE s.reading_id IS NULL ORDER BY a.asset_name;

3. SELECT a.asset_name FROM assets a WHERE NOT EXISTS (SELECT 1 FROM sensor_readings s WHERE s.asset_id = a.asset_id AND s.alarm_flag = 1) ORDER BY a.asset_name;
